CREATE TABLE votes (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,proposal_id BIGINT NOT NULL,direction VARCHAR(10) NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,CONSTRAINT uk_user_proposal UNIQUE(user_id,proposal_id),CONSTRAINT fk_votes_user FOREIGN KEY(user_id) REFERENCES users(id),CONSTRAINT fk_votes_proposal FOREIGN KEY(proposal_id) REFERENCES proposals(id),INDEX idx_votes_proposal(proposal_id));
